        journal.post_entry(self.journal, "rent", [("6100", 900, 0), ("1000", 0, 900)])
        journal.post_entry(self.journal, "fee", [("6200", 30, 0), ("1000", 0, 30)])
        self.assertEqual(len(self.journal.lines()), 4)

